[CmdletBinding()]
param([Parameter(Mandatory)][string]$Simfile,[Parameter(Mandatory)][string]$Preview,[Parameter(Mandatory)][switch]$Approved,[int]$Width=836,[int]$Height=328)
$ErrorActionPreference='Stop'; if(-not $Approved){throw 'Explicit -Approved is required after owner approval of the exact preview.'}
$inspect=& (Join-Path $PSScriptRoot 'Inspect-Banner.ps1') -Simfile $Simfile; $source=(Resolve-Path -LiteralPath $Preview).Path; $target=$inspect.BannerPath; $beforeReference=$inspect.BannerReference
$stamp=Get-Date -Format 'yyyyMMdd-HHmmss'; $backup="$target.pre-upscale-$stamp.bak"; $temp=Join-Path (Split-Path -Parent $target) ('.banner-install-'+[guid]::NewGuid().ToString('N')+'.png')
Add-Type -AssemblyName System.Drawing; $input=[Drawing.Image]::FromFile($source)
try{$bitmap=New-Object Drawing.Bitmap $Width,$Height,([Drawing.Imaging.PixelFormat]::Format32bppArgb);try{$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.CompositingQuality=[Drawing.Drawing2D.CompositingQuality]::HighQuality;$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$g.DrawImage($input,0,0,$Width,$Height);$bitmap.Save($temp,[Drawing.Imaging.ImageFormat]::Png)}finally{$g.Dispose()}}finally{$bitmap.Dispose()}}finally{$input.Dispose()}
try{Copy-Item -LiteralPath $target -Destination $backup;Move-Item -LiteralPath $temp -Destination $target -Force;$after=& (Join-Path $PSScriptRoot 'Inspect-Banner.ps1') -Simfile $Simfile;if($after.Width-ne$Width-or$after.Height-ne$Height){throw 'Installed PNG dimensions failed validation.'};if($after.BannerReference-cne$beforeReference){throw '#BANNER reference changed unexpectedly.'};[pscustomobject]@{Installed=$target;Backup=$backup;Width=$after.Width;Height=$after.Height;BannerReference=$after.BannerReference;RestartedITGmania=$false}}catch{if(Test-Path -LiteralPath $backup){Copy-Item -LiteralPath $backup -Destination $target -Force};throw}finally{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}}
